<script setup>
import { computed } from 'vue';
const props = defineProps({ title: { type: String, required: true }, data: { type: Array, required: true }, type: { type: String, default: 'bar' }, valueLabel: { type: Function, default: (value) => value.toLocaleString() } });
const max = computed(() => Math.max(...props.data.map((item) => Number(item.value)), 1));
const points = computed(() => props.data.map((item, index) => `${props.data.length === 1 ? 50 : (index / Math.max(props.data.length - 1, 1)) * 100},${92 - ((Number(item.value) / max.value) * 78)}`).join(' '));
const total = computed(() => props.data.reduce((sum, item) => sum + Number(item.value), 0));
const colors = ['#0797A5', '#0B3D6E', '#38BDF8', '#10B981', '#F59E0B', '#8B5CF6', '#EF4444', '#64748B'];
</script>
<template>
<section class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm" :aria-label="title"><h2 class="text-base font-bold text-slate-900">{{ title }}</h2>
<div v-if="data.length && type === 'line'" class="mt-5"><svg viewBox="0 0 100 100" class="h-56 w-full overflow-visible" role="img" :aria-label="`${title} line chart`" preserveAspectRatio="none"><line v-for="y in [14,40,66,92]" :key="y" x1="0" :y1="y" x2="100" :y2="y" stroke="#e2e8f0" stroke-width=".5"/><polyline :points="points" fill="none" stroke="#0797A5" stroke-width="2.5" vector-effect="non-scaling-stroke"/><circle v-for="(point,index) in data" :key="point.label" :cx="data.length===1?50:(index/Math.max(data.length-1,1))*100" :cy="92-((Number(point.value)/max)*78)" r="1.6" fill="#0B3D6E"><title>{{ point.label }}: {{ valueLabel(Number(point.value)) }}</title></circle></svg><div class="mt-2 flex justify-between text-[10px] text-slate-500"><span>{{ data[0]?.label }}</span><span>{{ data[data.length-1]?.label }}</span></div></div>
<div v-else-if="data.length && type === 'doughnut'" class="mt-5 grid gap-6 sm:grid-cols-[10rem_1fr] sm:items-center"><div class="relative mx-auto h-40 w-40 rounded-full" :style="{background:`conic-gradient(${data.map((item,i)=>`${colors[i%colors.length]} ${data.slice(0,i).reduce((s,v)=>s+Number(v.value),0)/Math.max(total,1)*100}% ${data.slice(0,i+1).reduce((s,v)=>s+Number(v.value),0)/Math.max(total,1)*100}%`).join(',')})`}"><div class="absolute inset-7 grid place-items-center rounded-full bg-white text-center"><span><strong class="block text-2xl text-slate-900">{{ total.toLocaleString() }}</strong><small class="text-slate-500">Total</small></span></div></div><ul class="space-y-2 text-sm"><li v-for="(item,index) in data" :key="item.label" class="flex items-center justify-between gap-3"><span class="flex items-center gap-2 text-slate-600"><i class="h-2.5 w-2.5 rounded-full" :style="{backgroundColor:colors[index%colors.length]}"/>{{ item.label }}</span><strong>{{ valueLabel(Number(item.value)) }}</strong></li></ul></div>
<div v-else-if="data.length" class="mt-5 flex h-56 items-end gap-2 border-b border-slate-200 px-1"><div v-for="(item,index) in data" :key="item.label" class="group flex min-w-0 flex-1 flex-col items-center justify-end gap-2" :title="`${item.label}: ${valueLabel(Number(item.value))}`"><span class="hidden text-[10px] font-semibold text-slate-600 group-hover:block">{{ valueLabel(Number(item.value)) }}</span><div class="w-full max-w-12 rounded-t-md" :style="{height:`${Math.max((Number(item.value)/max)*170,item.value?4:1)}px`,backgroundColor:colors[index%colors.length]}"/><span class="w-full truncate pb-2 text-center text-[9px] text-slate-500">{{ item.label }}</span></div></div><p v-else class="grid h-56 place-items-center text-sm text-slate-400">No data in this period</p>
<table class="sr-only"><caption>{{ title }}</caption><tbody><tr v-for="item in data" :key="item.label"><th>{{ item.label }}</th><td>{{ valueLabel(Number(item.value)) }}</td></tr></tbody></table></section>
</template>
